-- Edges of a diagram (change us-074-diagram-connections; docs/data-model.puml, business-objects/diagram.md, ADR-019,
-- ADR-030). Runs as oea_owner. An edge shows a connection from a shape of its source entity to a shape of its target
-- entity; the bend points are in pt with at most two decimals. The edges of a diagram are replaced as a whole on each
-- save, like its shapes.

CREATE TABLE diagram_edges (
    -- generated by the client and stable across saves
    id              UUID    PRIMARY KEY,
    diagram_id      UUID    NOT NULL REFERENCES diagrams (id) ON DELETE CASCADE,
    -- no cascade: entities are never removed for good in v1.0 (ADR-019); a deleted connection hides its edges
    connection_id   INTEGER NOT NULL REFERENCES entities (id),
    -- removing a shape removes its edges
    source_shape_id UUID    NOT NULL REFERENCES diagram_shapes (id) ON DELETE CASCADE,
    target_shape_id UUID    NOT NULL REFERENCES diagram_shapes (id) ON DELETE CASCADE,
    -- [[x, y], ...] in pt from source to target, at most 50 (checked by the service)
    points          JSONB   NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(points) = 'array')
);

CREATE INDEX diagram_edges_diagram ON diagram_edges (diagram_id);
CREATE INDEX diagram_edges_connection ON diagram_edges (connection_id);

REVOKE ALL ON diagram_edges FROM PUBLIC;

-- Runtime role: the save replaces the edges of a diagram
GRANT SELECT, INSERT, UPDATE, DELETE ON diagram_edges TO oea_app;
